source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    crosses = {}
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
            if all(grid[rr][cc] == 3 for rr, cc in arms):
                crosses[(r, c)] = arms

    out = [row[:] for row in grid]
    cores = [(pos, grid[pos[0]][pos[1]]) for pos in crosses
             if grid[pos[0]][pos[1]] not in (0, 3)]
    arm_owner = {arm: center for center, arms in crosses.items() for arm in arms}
    empty_centers = [pos for pos in crosses if grid[pos[0]][pos[1]] == 0]

    def paint(center, color, dr, dc):
        r, c = center
        while 0 <= r < h and 0 <= c < w:
            owner = arm_owner.get((r, c))
            if owner is not None and owner != center:
                break
            if grid[r][c] == 0:
                out[r][c] = color
            r += dr
            c += dc

    # Horizontal projections, including the empty horizontal axes.
    for center, color in cores:
        for dc in (-1, 1):
            paint(center, color, 0, dc)
    for r, c in empty_centers:
        for cc in range(w):
            if grid[r][cc] == 0:
                out[r][cc] = 0

    # Vertical projections take precedence over horizontal ones.
    for r, c in empty_centers:
        for rr in range(h):
            if grid[rr][c] == 0:
                out[rr][c] = 0
    for center, color in cores:
        for dr in (-1, 1):
            paint(center, color, dr, 0)
    return out
'''
